    /* all doors are initially closed */
    do i = 1 to numdoors;
      doors(i) = closed_door;
    end;

    /* cycle through at increasing intervals and flip doors */
    do i = 1 to numdoors;
      j = i;
      do while (j <= numdoors);
        doors(j) = ^doors(j);
        j = j + i;
      end;
    end;

    /* show results - open doors should all be perfect squares */
    put skip list ('The open doors are:');
    do i = 1 to numdoors;
      if doors(i) = open_door then
        put edit (i) (F(4));
    end;

end hundred_doors;

