import Std.Math.*;
operation HundredDoors () : Int[] {
  use q = Qubit();
  mutable doors = [];
  for n in 1..100 {
    for g in 1..n{
      let (_,r)=DivRemI(n,g);
      if (r==0) {X(q)};
    }
    if (M(q)==One) {doors+=[n];}
    Reset(q);
  }
  return doors;
}

