    return $r
}

proc toggle {val a b} {
    # expr has ternary operators
    return  [expr {
                ${val} == ${a}? ${b} :
                ${val} == ${b}? ${a} :
                [error "bad value: ${val}"]
            }]
}

proc multiples {n max} {
    set ret {}
    set x $n

    # maximum multiple
    set mid  [expr $max / 2]

    if {$x>=$mid  &&  $x<$max} { return $x }

    # calculate multiples
    if {[expr $x <= $mid]} {
        for {set i 1} {$i <= $max } {incr i} {

            set x [expr $i * $n]

               if {$x > $max} { break }

            lappend ret $x
        }
    }

    return $ret
}

